from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class GetParametersASMV1(SchemaObject):
    nidd_id = SchemaField(name='niddId', not_null=True)
    parameters = SchemaField(name='parameters', not_null=True)

    def __init__(self, nidd_id, parameters):
        self.nidd_id = nidd_id
        self.parameters = [Parameter.from_object_dict(param) for param in parameters]
        super(GetParametersASMV1, self).__init__()


class Parameter(SchemaObject):
    complex_parameter = SchemaField(name="complexParameter")
    parameter_type = SchemaField(name="parameterType")
    simple_list_parameter = SchemaField(name="simpleListParameter")
    simple_parameter = SchemaField(name="simpleParameter")

    def __init__(self, complex_parameter, parameter_type, simple_list_parameter, simple_parameter):
        self.complex_parameter = complex_parameter
        self.parameter_type = parameter_type
        self.simple_list_parameter = simple_list_parameter
        self.simple_parameter = simple_parameter
        super(Parameter, self).__init__()
